/* v4.2.7: grouped metric cards. Synthetic HTML records only; never writes SQLite. */
const MT_GROUPS=[['tumor','肿瘤标志物'],['cbc','血常规'],['liver','肝功能'],['kidney','肾功能与电解质'],['inflammation','炎症与感染相关'],['nutrition','营养相关'],['body','身体测量']];
const MT_CATALOG={
 cea:{...METRICS.cea,category:'tumor'},cyfra:{...METRICS.cyfra,category:'tumor'},nse:{...METRICS.nse,category:'tumor'},scc:{...METRICS.scc,category:'tumor'},progrp:{name:'ProGRP',unit:'pg/mL',category:'tumor'},
 wbc:{...METRICS.wbc,category:'cbc'},anc:{name:'中性粒细胞绝对值',unit:'×10⁹/L',category:'cbc'},hb:{...METRICS.hb,category:'cbc'},plt:{name:'血小板',unit:'×10⁹/L',category:'cbc'},
 alt:{...METRICS.alt,category:'liver'},ast:{name:'AST',unit:'U/L',category:'liver'},creatinine:{name:'肌酐',unit:'μmol/L',category:'kidney'},potassium:{name:'血钾',unit:'mmol/L',category:'kidney'},crp:{name:'CRP',unit:'mg/L',category:'inflammation'},albumin:{name:'白蛋白',unit:'g/L',category:'nutrition'},weight:{name:'体重',unit:'kg',category:'body'}
};
const mtExtra=[],mtFlipped=new Set();let mtSeq=0;
function mtObservations(){const p=current(),rows=[];for(const [key,series] of Object.entries(p.series)){const m=MT_CATALOG[key];if(!m)continue;series.forEach(([date,value],i)=>rows.push({id:`${p.id}-${key}-${i}`,key,date,value,unit:m.unit,method:'模拟检测方法 A',laboratory:'模拟检验机构 A',source:`模拟报告 ${date}`,reference:null,state:'accepted'}))}if(p.weight) p.weight.forEach(([date,value],i)=>rows.push({id:`${p.id}-weight-${i}`,key:'weight',date,value,unit:'kg',method:'模拟同一电子秤',laboratory:'模拟家庭记录',source:`模拟体重记录 ${date}`,reference:null,state:'accepted'}));return rows.concat(mtExtra.filter(r=>r.owner===p.id))}
function mtSeries(key){const map=new Map();for(const r of mtObservations().filter(r=>r.key===key&&r.state==='accepted')){const id=[key,r.unit||'单位未知',r.method||'方法未知',r.laboratory||'机构未知'].join('|');if(!map.has(id))map.set(id,{id,key,unit:r.unit,method:r.method,laboratory:r.laboratory,rows:[]});map.get(id).rows.push(r)}return [...map.values()].map(s=>({...s,rows:s.rows.sort((a,b)=>a.date.localeCompare(b.date))}))}
function mtCard(s){const m=MT_CATALOG[s.key],rows=s.rows,last=rows.at(-1),prev=rows.at(-2),comparable=!!(s.unit&&s.method&&s.laboratory),delta=last&&prev&&comparable?Number((last.value-prev.value).toPrecision(5)):null,id=current().id+'|'+s.id,flip=mtFlipped.has(id),group=MT_GROUPS.find(([key])=>key===m.category),deltaText=delta===null?(rows.length<2?'暂无可比较的前次记录':'方法 / 机构未齐，仅显示记录点'):`${delta>0?'↑':delta<0?'↓':'→'} 较前次 ${delta>0?'+':''}${delta}`;
 return `<article class="mt-card ${flip?'is-flipped':''} ${!last?'is-empty':''}" role="group" tabindex="0" aria-roledescription="可翻转指标卡" aria-label="${esc(m.name)}，${last?'点击或回车查看趋势':'暂无记录，点击查看说明'}" data-action="mt-flip" data-series="${esc(id)}"><div class="mt-card-inner">
 <div class="mt-card-face mt-front" aria-hidden="${flip}" ${flip?'inert':''}><span class="mt-category"><i data-category="${m.category}"></i>${group[1]}</span><h3>${esc(m.name)}</h3>${last?`<div class="mt-value">${last.value}<small>${esc(s.unit||'单位待核')}</small></div><p class="mt-delta">${esc(deltaText)}</p><div class="mt-card-foot"><span>共 ${rows.length} 次 · ${esc(last.date)}<br>${esc(last.source)}<br><span class="mt-method-meta" title="${esc((s.method||'方法未知')+' · '+(s.laboratory||'机构未知'))}">${esc(s.method||'方法未知')} · ${esc(s.laboratory||'机构未知')}</span></span><span>点开看趋势 ↻</span></div>`:`<p class="mt-no-value">还没有记录。<br>导入检验单或手工补录后显示。</p><div class="mt-card-foot"><span>目录单位 ${esc(m.unit)}<br>不是检查推荐</span><span>无数据</span></div>`}</div>
 <div class="mt-card-face mt-back" aria-hidden="${!flip}" ${!flip?'inert':''}><div class="mt-back-head"><b>${esc(m.name)} · 趋势</b><small>${esc(s.unit||m.unit)}</small></div><div class="mt-chart-body">${last?mtChart(s):'<div class="mt-no-chart">没有可回顾的数值，不绘制0或假曲线。</div>'}</div><p class="mt-comparison">${esc(s.method||'检测方法未知')} · ${esc(s.laboratory||'检测机构未知')}<br>单点不连线；点选数据点查看来源，再次点击卡片返回数值。</p></div>
 </div></article>`
}
function mtChart(s){const rows=s.rows,w=420,left=48,right=400,top=18,bottom=130,min=Math.min(...rows.map(r=>r.value)),max=Math.max(...rows.map(r=>r.value)),pad=min===max?Math.max(Math.abs(min)*.1,1):0,lo=min-pad/2,hi=max+pad/2,points=rows.map(r=>({x:dateAxisX(r.date,rows[0].date,rows.at(-1).date,left,right),y:bottom-(r.value-lo)/(hi-lo||1)*(bottom-top),row:r}));return `<svg viewBox="0 0 420 166" role="group" aria-label="${esc(MT_CATALOG[s.key].name)}，${rows.length}个记录点，${esc(s.unit||'单位未知')}">${[0,.5,1].map(t=>{const y=bottom-(bottom-top)*t;return `<line x1="${left}" x2="${right}" y1="${y}" y2="${y}" stroke="#dbe8ef"/><text x="40" y="${y+4}" text-anchor="end">${Number((lo+(hi-lo)*t).toPrecision(4))}</text>`}).join('')}${s.method&&s.laboratory&&s.unit&&rows.length>1?`<path d="${smoothMetricPath(points)}" fill="none" stroke="#387b9e" stroke-width="2.5"/>`:''}${points.map(p=>`<g><circle cx="${p.x}" cy="${p.y}" r="4" fill="#387b9e" stroke="white" stroke-width="2"/><circle cx="${p.x}" cy="${p.y}" r="13" fill="transparent" role="button" tabindex="0" aria-label="${esc(MT_CATALOG[s.key].name+' '+p.row.date+' '+p.row.value+' '+(s.unit||'')+' 查看来源')}" data-action="mt-source" data-observation="${esc(p.row.id)}"/></g>`).join('')}<text x="${left}" y="158">${rows[0].date.slice(2)}</text><text x="${right}" y="158" text-anchor="end">${rows.at(-1).date.slice(2)}</text></svg>`}
function mtLatestReport(category){const rows=mtObservations().filter(r=>r.state==='accepted'&&MT_CATALOG[r.key]?.category===category);if(!rows.length)return '';const latest=rows.map(r=>r.date).sort().at(-1),source=rows.find(r=>r.date===latest).source,report=rows.filter(r=>r.date===latest&&r.source===source);return `<div class="card mt-latest-report">${section(`最近一次${MT_GROUPS.find(([key])=>key===category)[1]}（${latest}）`,'参考区间随原件保留；不同日期或报告不拼成同一张化验单。',tag('模拟已核对','green'))}${dataTable(['项目','结果','单位','参考区间原文','来源'],report.map(r=>[MT_CATALOG[r.key].name,r.value,esc(r.unit||'未记录'),esc(r.reference||'未转录'),`<button class="link-btn" data-action="mt-source" data-observation="${esc(r.id)}">${esc(r.source)}</button>`]))}</div>`}
function recordsMetrics(){const pending=mtObservations().filter(r=>r.state!=='accepted');return `<div class="mt-view"><div class="info-box">趋势只呈现记录，不代表疗效、复发或诊断判断；同名指标按单位、方法与机构分开。箭头仅表示数值方向，不表示好坏。</div><div class="row mt-toolbar">${btn('＋ 手工补录一个值','mt-add','btn primary')}${btn('导入检验单','go','btn','data-page="archives"')}${btn('去一图秀看趋势','go','btn','data-page="timeline"')}</div>${pending.length?`<div class="info-box">${pending.length}条补录草稿待核对，尚未进入卡片或趋势。${btn('去整理草稿 / 核对','go','btn small','data-page="records" data-sub="整理草稿 / 核对"')}</div>`:''}${MT_GROUPS.map(([category,title])=>{const entries=Object.entries(MT_CATALOG).filter(([,m])=>m.category===category),count=entries.filter(([key])=>mtSeries(key).length).length,series=entries.flatMap(([key])=>{const data=mtSeries(key);return data.length?data:[{id:key+'|empty',key,unit:MT_CATALOG[key].unit,method:'',laboratory:'',rows:[]}]});return `<details class="mt-category-section" ${count||category==='tumor'||category==='cbc'?'open':''}><summary><h2>${title}</h2><span>${entries.length}项 · ${count}项有记录${series.length>entries.length?' · '+series.length+'个可比组':''}</span></summary><div class="mt-card-grid">${(count?series.filter(s=>s.rows.length):series.slice(0,2)).map(mtCard).join('')}</div>${(count?series.filter(s=>!s.rows.length):series.slice(2)).length?`<details class="mt-unrecorded"><summary>展开其余 ${ (count?series.filter(s=>!s.rows.length):series.slice(2)).length } 项未记录指标</summary><div class="mt-card-grid">${(count?series.filter(s=>!s.rows.length):series.slice(2)).map(mtCard).join('')}</div></details>`:''}${mtLatestReport(category)}</details>`}).join('')}</div>`}
function mtSource(id){const row=mtObservations().find(r=>r.id===id);if(!row)return;modal('指标原始记录',`<div class="stack"><h3>${esc(MT_CATALOG[row.key].name)} · ${row.value} ${esc(row.unit||'单位未知')}</h3><p>${esc(row.date)} · ${esc(row.source)}</p><p>检测方法：${esc(row.method||'未记录')}<br>检测机构：${esc(row.laboratory||'未记录')}<br>参考区间原文：${esc(row.reference||'未转录')}</p><div class="info-box">这是HTML合成演示记录。不会自动确认医学含义，也没有真实报告文件。</div></div>`,btn('返回指标','close','btn primary'),'来源与可比性')}
function mtAdd(){modal('手工补录一个值',`<form id="mt-form" class="form-grid"><div class="info-box full">仅在当前HTML页面内存中演示。核对前是候选，刷新清空，不写SQLite。</div><div class="field"><label for="mt-form-key">项目</label><select id="mt-form-key" name="key">${Object.entries(MT_CATALOG).map(([key,m])=>`<option value="${key}">${m.name}</option>`).join('')}</select></div><div class="field"><label for="mt-form-date">采样日期</label><input id="mt-form-date" name="date" type="date" required></div><div class="field"><label for="mt-form-value">原始数值</label><input id="mt-form-value" name="value" type="number" step="any" required></div><div class="field"><label for="mt-form-unit">报告单位</label><input id="mt-form-unit" name="unit" value="ng/mL" placeholder="以报告原文为准"></div><div class="field"><label for="mt-form-method">检测方法（可空）</label><input id="mt-form-method" name="method"></div><div class="field"><label for="mt-form-laboratory">检测机构（可空）</label><input id="mt-form-laboratory" name="laboratory"></div><div class="field"><label for="mt-form-reference">参考区间原文（可空）</label><input id="mt-form-reference" name="reference"></div><div class="field"><label for="mt-form-source">报告来源</label><input id="mt-form-source" name="source" required placeholder="例如模拟10月检验单"></div></form>`,`${btn('取消','close','btn')}<button type="submit" form="mt-form" class="btn primary">存为待核对草稿</button>`,'补录 · HTML模拟')}
function mtPending(){const pending=mtObservations().filter(r=>r.state!=='accepted');return pending.length?`<div class="card">${section('指标补录草稿','逐条对照原件，确认只表示转录一致。')}${pending.map(r=>`<div class="list-row"><div class="body"><b>${esc(MT_CATALOG[r.key].name)} · ${r.value} ${esc(r.unit||'单位未知')}</b><p>${esc(r.date)} · ${esc(r.source)}</p></div>${btn('查看来源','mt-source','btn small',`data-observation="${esc(r.id)}"`)}${btn('核对并纳入指标','mt-confirm','btn small primary',`data-observation="${esc(r.id)}"`)}</div>`).join('')}</div>`:''}
function mtSummary(){const rows=mtObservations().filter(r=>r.state==='accepted');return `<div class="card">${section('病情汇总','从已核对资料生成回顾，不新增诊断或推断。')}${dataTable(['资料','内容'],[['病理 / 分型',esc(current().path)],['分子报告原文',esc(current().gene)],['治疗记录',esc(current().treatment)],['已核对指标',`${rows.length}条合成记录`]])}<div class="row">${btn('查看分类指标','go','btn','data-page="records" data-sub="指标检测"')}${btn('准备复诊问题','go','btn primary','data-page="review"')}</div></div>`}
function mtFlip(card){const key=card.dataset.series,on=!card.classList.contains('is-flipped');card.classList.toggle('is-flipped',on);if(on)mtFlipped.add(key);else mtFlipped.delete(key);const front=card.querySelector('.mt-front'),back=card.querySelector('.mt-back');front.inert=on;back.inert=!on;front.setAttribute('aria-hidden',String(on));back.setAttribute('aria-hidden',String(!on))}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||!target.dataset.action.startsWith('mt-'))return;e.stopImmediatePropagation();const a=target.dataset.action;if(a==='mt-source')return mtSource(target.dataset.observation);if(a==='mt-flip')return mtFlip(target);if(a==='mt-add')return mtAdd();if(a==='mt-confirm'){const row=mtExtra.find(r=>r.id===target.dataset.observation&&r.owner===current().id);if(row){row.state='accepted';render();toast('模拟转录已核对，可在指标检测查看')}}},true);
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const target=e.target;if(target.matches('.mt-card,[data-action="mt-source"]')){e.preventDefault();target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('change',e=>{if(e.target.matches('#mt-form select[name="key"]'))e.target.form.elements.unit.value=MT_CATALOG[e.target.value].unit});
document.addEventListener('submit',e=>{if(e.target.id!=='mt-form')return;e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(e.target)),value=Number(data.value);if(!Number.isFinite(value)||!validMetricDay({precision:'day',value:data.date})){toast('请核对有效日期和数值');return}mtExtra.push({...data,value,id:'mt-extra-'+(++mtSeq),owner:current().id,state:'candidate'});closeModal();navigate('records','整理草稿 / 核对');toast('已保存待核对模拟记录，尚未进入正式趋势')},true);
